UPDATE qr_keyterm_story SET explain_en = '43:4: "It is with Us in the Mother of the Book, exalted, full of wisdom." 13:39: "God erases what He wills and keeps; with Him is the Mother of the Book." One Book is both God’s record and the source of every revelation.' WHERE id = 'KS:kitab:2';
UPDATE qr_keyterm_story SET title_en = 'After Mūsā' WHERE id = 'KS:kitab:3';
INSERT OR REPLACE INTO qr_keyterm_story (id, term_grp, term_ar, seq, title_en, surah, ayah_from, word_from, ayah_to, word_to, marks_json, ask_en, answer_en, wrong_json, explain_en, status, gc_ref, step_gc_ref, topic_ref, term_key, match_json, layer, source_ref, term_en, term_root, deck_slug) VALUES ('KS:kitab:13', 're_skt_e709096b4073716c', 'الكِتَاب', 1, 'A word for writing', 27, 29, 1, 29, 999, '[[29, 7, 8]]', 'When Sulaymān’s letter reached the queen of Sabaʾ, what did she call it?', 'A noble kitāb', '["A clear sign", "A sealed promise", "A heavenly scroll"]', '27:29: "Chiefs, a noble kitāb has been delivered to me." Kitāb is first of all something written — from kataba, to write. The Qurʾān takes this plain word and lifts it to mean the Book of God.', 'live', 'GC:quran:kitab', 'GC:quran:kitab', 'QR:TOP:kitab', 'kitab', '{"sinai":["re_skt_e709096b4073716c"]}', 'quran', 'sinai:key-terms:kitab', 'al-Kitāb', 'كتب', 'qr-keyterm-story-kitab');
INSERT OR REPLACE INTO qr_keyterm_story (id, term_grp, term_ar, seq, title_en, surah, ayah_from, word_from, ayah_to, word_to, marks_json, ask_en, answer_en, wrong_json, explain_en, status, gc_ref, step_gc_ref, topic_ref, term_key, match_json, layer, source_ref, term_en, term_root, deck_slug) VALUES ('KS:kitab:14', 're_skt_e709096b4073716c', 'الكِتَاب', 2, 'A record of everything', 78, 29, 1, 29, 999, '[[29, 1, 4]]', 'What has God written down in a Book?', 'Everything', '["Only the deeds of people", "Only the names of the prophets", "Only the laws"]', '78:29: "And everything We have counted in a Book." The first Book is God’s own record: nothing is left out of it.', 'live', 'GC:quran:kitab', 'GC:quran:kitab', 'QR:TOP:kitab', 'kitab', '{"sinai":["re_skt_e709096b4073716c"]}', 'quran', 'sinai:key-terms:kitab', 'al-Kitāb', 'كتب', 'qr-keyterm-story-kitab');
INSERT OR REPLACE INTO qr_keyterm_story (id, term_grp, term_ar, seq, title_en, surah, ayah_from, word_from, ayah_to, word_to, marks_json, ask_en, answer_en, wrong_json, explain_en, status, gc_ref, step_gc_ref, topic_ref, term_key, match_json, layer, source_ref, term_en, term_root, deck_slug) VALUES ('KS:kitab:15', 're_skt_e709096b4073716c', 'الكِتَاب', 4, 'The hidden Book', 56, 77, 1, 79, 999, '[[78, 2, 3], [79, 2, 4]]', 'Who alone touches the hidden Book?', 'The purified ones', '["The scholars", "The kings", "The poets"]', '56:77–79: "It is a noble Qurʾān, in a hidden Book, which none touch but the purified." The purified are the angels: the Book is out of every other reach.', 'live', 'GC:quran:kitab', 'GC:quran:lawh_mahfuz', 'QR:TOP:kitab', 'kitab', '{"sinai":["re_skt_e709096b4073716c"]}', 'quran', 'sinai:key-terms:kitab', 'al-Kitāb', 'كتب', 'qr-keyterm-story-kitab');
INSERT OR REPLACE INTO qr_keyterm_story (id, term_grp, term_ar, seq, title_en, surah, ayah_from, word_from, ayah_to, word_to, marks_json, ask_en, answer_en, wrong_json, explain_en, status, gc_ref, step_gc_ref, topic_ref, term_key, match_json, layer, source_ref, term_en, term_root, deck_slug) VALUES ('KS:kitab:16', 're_skt_e709096b4073716c', 'الكِتَاب', 6, 'Set out as an Arabic recitation', 41, 3, 1, 3, 999, '[[3, 1, 5]]', 'How did the Book with God come to people?', 'Its verses set out as an Arabic Qurʾān', '["As tablets of stone", "As a single scroll from the sky", "As dreams to the wise"]', '41:3: "A Book whose verses are set out in detail, an Arabic Qurʾān, for people who know." The Book above becomes words people can hear and understand.', 'live', 'GC:quran:kitab', 'GC:quran:kitab', 'QR:TOP:kitab', 'kitab', '{"sinai":["re_skt_e709096b4073716c"]}', 'quran', 'sinai:key-terms:kitab', 'al-Kitāb', 'كتب', 'qr-keyterm-story-kitab');
INSERT OR REPLACE INTO qr_keyterm_story (id, term_grp, term_ar, seq, title_en, surah, ayah_from, word_from, ayah_to, word_to, marks_json, ask_en, answer_en, wrong_json, explain_en, status, gc_ref, step_gc_ref, topic_ref, term_key, match_json, layer, source_ref, term_en, term_root, deck_slug) VALUES ('KS:kitab:17', 're_skt_e709096b4073716c', 'الكِتَاب', 12, 'The Book of Mūsā', 46, 12, 1, 12, 999, '[[12, 3, 6]]', 'What does the Qurʾān call the Book that came before it?', 'The Book of Mūsā, a guide and a mercy', '["The poems of the ancients", "The wisdom of Luqmān", "The scrolls of Nūḥ"]', '46:12: "Before it was the Book of Mūsā, a guide and a mercy; and this is a Book confirming it, in the Arabic tongue." Two Books, one source.', 'live', 'GC:quran:kitab', 'GC:quran:tawrat', 'QR:TOP:kitab', 'kitab', '{"sinai":["re_skt_e709096b4073716c"]}', 'quran', 'sinai:key-terms:kitab', 'al-Kitāb', 'كتب', 'qr-keyterm-story-kitab');
INSERT OR REPLACE INTO qr_keyterm_story (id, term_grp, term_ar, seq, title_en, surah, ayah_from, word_from, ayah_to, word_to, marks_json, ask_en, answer_en, wrong_json, explain_en, status, gc_ref, step_gc_ref, topic_ref, term_key, match_json, layer, source_ref, term_en, term_root, deck_slug) VALUES ('KS:kitab:18', 're_skt_e709096b4073716c', 'الكِتَاب', 13, 'The same message, long before', 87, 18, 1, 19, 999, '[[18, 4, 5], [19, 1, 3]]', 'Where was this message written before?', 'In the first scrolls — of Ibrāhīm and Mūsā', '["Nowhere — it is new", "In the poems of Mecca", "In the tablets of Babylon"]', '87:18–19: "This is in the first scrolls, the scrolls of Ibrāhīm and Mūsā." The early sūras say ṣuḥuf, "scrolls", where later ones say kitāb.', 'live', 'GC:quran:kitab', 'GC:quran:kitab', 'QR:TOP:kitab', 'kitab', '{"sinai":["re_skt_e709096b4073716c"]}', 'quran', 'sinai:key-terms:kitab', 'al-Kitāb', 'كتب', 'qr-keyterm-story-kitab');
INSERT OR REPLACE INTO qr_keyterm_story (id, term_grp, term_ar, seq, title_en, surah, ayah_from, word_from, ayah_to, word_to, marks_json, ask_en, answer_en, wrong_json, explain_en, status, gc_ref, step_gc_ref, topic_ref, term_key, match_json, layer, source_ref, term_en, term_root, deck_slug) VALUES ('KS:kitab:19', 're_skt_e709096b4073716c', 'الكِتَاب', 14, 'Those who know it', 26, 196, 1, 197, 999, '[[196, 3, 4], [197, 7, 9]]', 'Who could tell that this message was in the books of old?', 'The learned of the Children of Isrāʾīl', '["The soothsayers of Arabia", "The priests of the idols", "The traders of Syria"]', '26:196–197: "It is in the writings of the ancients. Was it not a sign to them that the learned of the Children of Isrāʾīl know it?"', 'live', 'GC:quran:kitab', 'GC:quran:tawrat', 'QR:TOP:kitab', 'kitab', '{"sinai":["re_skt_e709096b4073716c"]}', 'quran', 'sinai:key-terms:kitab', 'al-Kitāb', 'كتب', 'qr-keyterm-story-kitab');
INSERT OR REPLACE INTO qr_keyterm_story (id, term_grp, term_ar, seq, title_en, surah, ayah_from, word_from, ayah_to, word_to, marks_json, ask_en, answer_en, wrong_json, explain_en, status, gc_ref, step_gc_ref, topic_ref, term_key, match_json, layer, source_ref, term_en, term_root, deck_slug) VALUES ('KS:kitab:20', 're_skt_e709096b4073716c', 'الكِتَاب', 20, 'What God writes on you', 2, 183, 1, 183, 999, '[[183, 4, 6]]', '"Kutiba ʿalaykum" — what does it mean when God writes something on you?', 'He makes it binding on you', '["He forgives it", "He hides it from you", "He records it as a sin"]', '2:183: "Fasting is written on you, as it was written on those before you." What God writes is His decree: kitāb can be a ruling as well as a Book.', 'live', 'GC:quran:kitab', 'GC:quran:kitab', 'QR:TOP:kitab', 'kitab', '{"sinai":["re_skt_e709096b4073716c"]}', 'quran', 'sinai:key-terms:kitab', 'al-Kitāb', 'كتب', 'qr-keyterm-story-kitab');
INSERT OR REPLACE INTO qr_keyterm_story (id, term_grp, term_ar, seq, title_en, surah, ayah_from, word_from, ayah_to, word_to, marks_json, ask_en, answer_en, wrong_json, explain_en, status, gc_ref, step_gc_ref, topic_ref, term_key, match_json, layer, source_ref, term_en, term_root, deck_slug) VALUES ('KS:kitab:21', 're_skt_e709096b4073716c', 'الكِتَاب', 21, 'The book in the right hand', 69, 19, 1, 19, 999, '[[19, 3, 5], [19, 7, 9]]', 'On the Day, what does the one given his book in his right hand say?', '“Here — read my book!”', '["“Hide it from me!”", "“I never wrote this!”", "“Give me another chance!”"]', '69:19: "As for the one given his book in his right hand, he will say: here, read my book!" Each person has a book of their own deeds.', 'live', 'GC:quran:kitab', 'GC:quran:kitab', 'QR:TOP:kitab', 'kitab', '{"sinai":["re_skt_e709096b4073716c"]}', 'quran', 'sinai:key-terms:kitab', 'al-Kitāb', 'كتب', 'qr-keyterm-story-kitab');
INSERT OR REPLACE INTO qr_keyterm_story (id, term_grp, term_ar, seq, title_en, surah, ayah_from, word_from, ayah_to, word_to, marks_json, ask_en, answer_en, wrong_json, explain_en, status, gc_ref, step_gc_ref, topic_ref, term_key, match_json, layer, source_ref, term_en, term_root, deck_slug) VALUES ('KS:kitab:22', 're_skt_e709096b4073716c', 'الكِتَاب', 22, 'Read your book', 17, 14, 1, 14, 999, '[[14, 1, 2]]', 'Who will be enough to judge you on the Day?', 'Your own self, reading your book', '["The angels, by vote", "Your family", "The people of your town"]', '17:14: "Read your book: you yourself are enough today to take account of you."', 'live', 'GC:quran:kitab', 'GC:quran:kitab', 'QR:TOP:kitab', 'kitab', '{"sinai":["re_skt_e709096b4073716c"]}', 'quran', 'sinai:key-terms:kitab', 'al-Kitāb', 'كتب', 'qr-keyterm-story-kitab');
INSERT OR REPLACE INTO qr_keyterm_story (id, term_grp, term_ar, seq, title_en, surah, ayah_from, word_from, ayah_to, word_to, marks_json, ask_en, answer_en, wrong_json, explain_en, status, gc_ref, step_gc_ref, topic_ref, term_key, match_json, layer, source_ref, term_en, term_root, deck_slug) VALUES ('KS:kitab:23', 're_skt_e709096b4073716c', 'الكِتَاب', 23, 'Nothing left out', 18, 49, 1, 49, 999, '[[49, 1, 2], [49, 13, 19]]', 'When the Book is laid open, what does it leave out?', 'Nothing, small or great', '["The small deeds", "The deeds done in secret", "The deeds of youth"]', '18:49: "The Book will be laid open … they will say: woe to us, what Book is this that leaves out nothing, small or great, but counts it!" The record of 78:29 is opened at last.', 'live', 'GC:quran:kitab', 'GC:quran:kitab', 'QR:TOP:kitab', 'kitab', '{"sinai":["re_skt_e709096b4073716c"]}', 'quran', 'sinai:key-terms:kitab', 'al-Kitāb', 'كتب', 'qr-keyterm-story-kitab');
UPDATE qr_keyterm_story SET word_from = 8, word_to = 19, marks_json = '[[49,13,19]]' WHERE id = 'KS:kitab:23';
